  'From 01/07/2025 there are 34 province-level units and no district level. Check this list against the official resolution and import the official ward / commune list before using it on patient records; old addresses on existing records are kept as entered.': 'Từ 01/07/2025 cả nước có 34 đơn vị hành chính cấp tỉnh và không còn cấp huyện. Hãy đối chiếu danh sách này với nghị quyết chính thức và nhập danh sách xã / phường chính thức trước khi dùng cho hồ sơ bệnh nhân; địa chỉ cũ trên hồ sơ đã có được giữ nguyên.',
