  'Records are never deleted — discontinued codes stay readable on old records and invoices. Every change is written to the activity history.': 'Bản ghi không bao giờ bị xoá — mã ngừng sử dụng vẫn hiển thị đúng trên hồ sơ, hoá đơn cũ. Mọi thay đổi đều ghi vào Lịch sử hoạt động.',
  'The code can no longer be chosen for new records. Existing records keep it.': 'Mã này không chọn được cho hồ sơ mới nữa. Hồ sơ đã có vẫn giữ nguyên.',
